#!/usr/bin/perl
# Differential fuzzer: control bytes and whitespace.
# Runs the C++ reference and the Rust port with IDENTICAL raw-byte argv,
# captures stdout to separate files, compares with cmp -s, compares exit codes.
use strict;
use warnings;
use POSIX ":sys_wait_h";

my $CPP  = "/workspace/dataset/test11_executable";
my $RUST = "/output/test11";
my $SCRATCH = "/tmp/wf-fuzz-r1-5";

# ------------------------------------------------------------------ helpers

my @CONTROLS = map { chr($_) } (0x01 .. 0x1f);
push @CONTROLS, chr(0x7f);
my @C1 = map { chr($_) } (0x80 .. 0x9f);      # C1 controls as raw high bytes
my @WS = (" ", "\t", "\n", "\r", chr(0x0b), chr(0x0c));
my @HOSTS = ("a", "abc", "Example.COM", "example.com", "xn--a", "XN--A",
             "xn--", ".", "..", "a.b", "a..b", "foo.bar.baz", "A");

my @CASES;   # each element: arrayref of argv strings
sub add { push @CASES, [ @_ ]; }

# ---- 1. every control / whitespace byte, bare and repeated
for my $c (@CONTROLS, @C1, @WS) {
    add($c);
    add($c x 2);
    add($c x 3);
    add($c x 7);
    add($c x 63);
    add($c x 64);
}

# ---- 2. control byte around / inside printable text, and vs "xn--" prefix
for my $c (@CONTROLS, @WS, @C1) {
    for my $h (@HOSTS) {
        add($c . $h);
        add($h . $c);
        add($c . $h . $c);
    }
    add("a" . $c . "b");
    add("a." . $c . ".b");
    add($c . ".");
    add("." . $c);
    add($c . "xn--" . $c);
    add("xn--" . $c);
    add("xn--" . $c . "ABC");
    add($c . "xn--abc");            # prefix pushed off offset 0
    add("X" . $c . "N--a");
    add("xn-" . $c . "-a");
}

# ---- 3. whitespace runs: leading / trailing / interior
for my $a (@WS) {
    for my $b (@WS) {
        add($a . $b);
        add($a . $b . "host");
        add("host" . $a . $b);
        add($a . "host" . $b);
        add("ho" . $a . $b . "st");
        add($a . "HOST.Example" . $b);
        add($a . $b . $a . $b . "x");
        for my $c (@WS) {
            add($a . $b . $c);
            add("a" . $a . $b . $c . "b");
        }
    }
}

# ---- 4. whitespace / control mixed with dots -> label counting
for my $w (@WS, @CONTROLS) {
    add($w . "." . $w . "." . $w);
    add("..." . $w);
    add("a" . $w . "b" . $w . "c");
    add($w . "." . $w . "." . $w . ".");
    add($w . "a." . $w . "b." . $w . "c" . $w);
}

# ---- 5. length boundaries built from control / whitespace bytes
for my $w (" ", "\t", "\n", "\r", chr(0x0b), chr(0x0c), chr(0x01), chr(0x1f), chr(0x7f)) {
    for my $n (0, 1, 2, 62, 63, 64, 65, 253, 254, 255, 256, 257, 300) {
        add($w x $n);
        my $k = $n > 0 ? $n - 1 : 0;
        add(("a" x $k) . $w);
        add($w . ("a" x $k));
    }
}

# ---- 6. control bytes mixed with uppercase (to_lower path)
for my $c (@CONTROLS, @C1) {
    add("ABC" . $c . "DEF");
    add("AB" . $c . "CD");
    add("XN--" . $c . "ZZ");
    add($c . "ABCDEFGHIJKLMNOPQRSTUVWXYZ" . $c);
    add($c . "abcdefghijklmnopqrstuvwxyz" . $c);
}

# ---- 7. every control byte adjacent to every whitespace byte
for my $c (@CONTROLS) {
    for my $w (@WS) {
        add($c . $w);
        add($w . $c);
        add("a" . $c . $w . "b");
    }
}

# ---- 8. deterministic pseudo-random control/whitespace soup
{
    my $state = 0x12345678;
    my $alpha = join("", @CONTROLS) . "\x7f. aAzZ.-" . join("", map { chr($_) } (0x80 .. 0x8f));
    my $len = length($alpha);
    for my $i (1 .. 700) {
        $state = ($state * 1103515245 + 12345) % 2147483648;
        my $n = 1 + ($state % 40);
        my $buf = "";
        for (1 .. $n) {
            $state = ($state * 1103515245 + 12345) % 2147483648;
            $buf .= substr($alpha, $state % $len, 1);
        }
        add($buf);
    }
}

# ---- 9. multi-argument invocations (several output lines)
add("\n", "\t", " ");
add("a\nb", "c\td", chr(0x01));
add("", "\n", "");
add(" ", "", "\x7f", "xn--\r");
add("\r\n", "\n\r");
add(chr(0x0b) . chr(0x0c), chr(0x0c) . chr(0x0b), chr(0x1f) . chr(0x01));
add("  leading", "trailing  ", "  both  ");
for my $c (@CONTROLS) {
    add($c, "a" . $c, $c . "a");
}
# ---- 10. single empty argument (argc > 1 but empty string)
add("");
add("", "");

# ------------------------------------------------------------------ runner

sub run_one {
    my ($bin, $outfile, $argv) = @_;
    my $pid = fork();
    die "fork failed" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $outfile) or POSIX::_exit(127);
        open(STDERR, '>', '/dev/null') or POSIX::_exit(127);
        exec { $bin } ($bin, @$argv);
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    return $? >> 8 | (($? & 127) << 8);   # encode signal separately
}

sub esc {
    my $s = shift;
    my $o = "";
    for my $ch (split //, $s) {
        my $b = ord($ch);
        if ($b >= 0x20 && $b < 0x7f && $ch ne '\\' && $ch ne '"') { $o .= $ch }
        else { $o .= sprintf('\\x%02x', $b) }
    }
    return '"' . $o . '"';
}

sub compare_case {
    my ($tag, $argv) = @_;
    my $cf = "$SCRATCH/c.$tag.out";
    my $rf = "$SCRATCH/r.$tag.out";
    my $ce = run_one($CPP,  $cf, $argv);
    my $re = run_one($RUST, $rf, $argv);
    my $same = (system("cmp", "-s", $cf, $rf) == 0) ? 1 : 0;
    return ($same && $ce == $re) ? (1, $ce, $re, $cf, $rf) : (0, $ce, $re, $cf, $rf);
}

sub slurp { local $/; open(my $fh, '<', $_[0]) or return "<none>"; binmode $fh; my $d = <$fh>; return defined($d) ? $d : ""; }

# --------------------------------------------------------------- parallel

my $NWORK = 12;
my $total = scalar @CASES;
my @kids;
for my $w (0 .. $NWORK - 1) {
    my $pid = fork();
    die "fork" unless defined $pid;
    if ($pid == 0) {
        open(my $rep, '>', "$SCRATCH/mismatch.$w.txt") or POSIX::_exit(1);
        binmode $rep;
        for (my $i = $w; $i < $total; $i += $NWORK) {
            my $argv = $CASES[$i];
            my ($ok, $ce, $re) = compare_case("w$w", $argv);
            next if $ok;
            # confirm twice before reporting
            my ($ok2, $ce2, $re2, $cf, $rf) = compare_case("w$w", $argv);
            my $kind = $ok2 ? "FLAKY" : "DIFF";
            print $rep "=" x 70, "\n";
            print $rep "$kind case #$i\n";
            print $rep "  argv = [", join(", ", map { esc($_) } @$argv), "]\n";
            print $rep "  cpp exit=$ce rust exit=$re (retry cpp=$ce2 rust=$re2)\n";
            print $rep "  cpp  stdout = ", esc(slurp($cf)), "\n";
            print $rep "  rust stdout = ", esc(slurp($rf)), "\n";
        }
        close $rep;
        POSIX::_exit(0);
    }
    push @kids, $pid;
}
waitpid($_, 0) for @kids;

my $nm = 0;
for my $w (0 .. $NWORK - 1) {
    my $f = "$SCRATCH/mismatch.$w.txt";
    next unless -s $f;
    open(my $fh, '<', $f) or next;
    while (my $l = <$fh>) { print $l; $nm++ if $l =~ /^(DIFF|FLAKY) case/; }
    close $fh;
}
print "\nTOTAL CASES EXECUTED: $total\n";
print "MISMATCHES: $nm\n";

